mapper.select:
/* 양수 게시글 목록 조회 */ SELECT ab.assignee_no, ab.cust_id, c.cust_nm , ab.product_category_no, pc.middle_category , pc.small_category , ab.products_nm, ab.rental_fee, ab.remaining_months, ab.desired_install_area, ab.quantity, ab.assignee_content, ab.board_valid_date, ab.register_date, ab.revision_date FROM customer c RIGHT JOIN assignee_board ab USING (cust_id) INNER JOIN products_category pc USING (product_category_no)
ab.products_nm LIKE CONCAT('%', #{searchValue}, '%')
ORDER BY
DATEDIFF(ab.board_valid_date, NOW()) ASC,
ab.register_date DESC LIMIT #{pageable.rowPerPage} OFFSET #{pageable.offset};
